//! The semantics differential: `mae_org::semantics` against mae-kb's org
//! parser (`parse_org_multi_result`), the projection it replaces (ADR-112 D2,
//! D5), over the bundled corpus and `tests/semantics/*.org`, plus an Emacs
//! oracle for titles and levels (`conformance/semantics-titles.tsv`,
//! generated by `conformance/gen-semantics-titles.sh` from Org's own parser,
//! so mae-org's plain-text reading is never judged by itself).
//!
//! Exactly what is compared, per file:
//! - **nodes**: the set of ids (a repeated id: its first node);
//! - per node: **title** (against mae-kb, and against the Emacs oracle),
//!   **level** (against the Emacs oracle only: mae-kb has none), **tags**
//!   (file tags then own), **kind**, **aliases**, **properties** (key by key),
//!   **todo**, **priority**, and **body** (against mae-kb's `Node.body`; see
//!   `compare_body`);
//! - **edges**: KB links with a source, as (source, target, fragment, rel,
//!   weight, confidence, attrs);
//! - **transclusions**: (source, member, role).
//!
//! NOT compared, so nothing here vouches for them: diagnostics; spans; a
//! link's description, search option (except where it explains a target,
//! class `id_search_option`) and path; links that are not KB edges (web,
//! mail, other schemes, local heading/custom-id/coderef targets: only their
//! absence from the edges is checked); a transclusion's args; and every
//! node mae-org does not produce (unrendered ones are only checked to be
//! diagnosed where a classifier says so).
//!
//! Every difference is first given a CLASS by a mechanical check that it is
//! one of the intended changes (`classify_*` below), or `unclassified`.
//! `conformance/semantics-divergences.toml` then lists, per class and file
//! pattern, why the difference is intended and which test pins mae-org's
//! side. An unlisted difference fails; so does an entry that matches
//! nothing, an entry whose pinning test is not a `#[test]` function, a
//! wildcard entry whose hit count changed, and an entry for one file
//! without a `detail`.
//!
//! The adapter maps `Semantics` to mae-kb's representation only where the
//! REPRESENTATION differs, never the meaning, and each mapping is what the O4
//! consumer will do: `ID` is a node field, not a property; a file node's
//! `KIND`/`ALIASES` are fields; a missing title is the id (file, item) or
//! empty (headline); a kind is `NodeKind::from_str_lossy` of the text; tags
//! are `Semantics::tags_of`; an edge is a KB link with a source and a target
//! or fragment; a body is compared through mae-kb's own `rewrite_links`,
//! which mae-kb applies to the text it stores.

mod support;

use mae_kb::org::{parse_org_multi_result, rewrite_links, ParsedLink};
use mae_kb::{Node, NodeKind};
use mae_org::seeded::HashMap;
use mae_org::{
    classify_link, parse, semantics, Document, LinkKind, NodeOrigin, ParseOptions,
    SemanticDiagnostic, SemanticNode, Semantics, SyntaxKind::*, TodoSequence,
};
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use support::{bundled_corpus, read, rel};

/// mae-kb hard-codes these TODO keywords; the differential declares the same
/// set (ADR-112 D4: they are data), so only in-file `#+TODO` lines differ.
fn options() -> ParseOptions {
    ParseOptions::default().with_todo_sequences(vec![TodoSequence::new(
        ["TODO", "NEXT", "WAIT"],
        ["DONE", "CANCELLED", "DEFERRED"],
    )])
}

#[derive(Debug, Clone)]
struct Diff {
    what: &'static str,
    class: &'static str,
    file: String,
    text: String,
}

/// One node in mae-kb's representation.
#[derive(Debug, Clone, PartialEq)]
struct Row {
    title: String,
    tags: Vec<String>,
    kind: NodeKind,
    aliases: Vec<String>,
    properties: BTreeMap<String, String>,
    todo: Option<String>,
    priority: Option<char>,
}

fn kb_row(n: &Node) -> Row {
    Row {
        title: n.title.clone(),
        tags: n.tags.clone(),
        kind: n.kind,
        aliases: n.aliases.clone(),
        properties: n.properties.clone().into_iter().collect(),
        todo: n.todo_state.clone(),
        priority: n.priority,
    }
}

fn sem_row(sem: &Semantics, n: &SemanticNode) -> Row {
    let title = n.title.clone().unwrap_or_else(|| match n.origin {
        NodeOrigin::Headline => String::new(),
        _ => n.id.clone(),
    });
    let file = n.origin == NodeOrigin::File;
    let is_field = |k: &str| k == "ID" || (file && (k == "KIND" || k == "ALIASES"));
    Row {
        title,
        tags: sem.tags_of(n),
        kind: NodeKind::from_str_lossy(n.kind.as_deref().unwrap_or("")),
        aliases: n.aliases.clone(),
        properties: n
            .properties
            .iter()
            .filter(|(k, _)| !is_field(k))
            .map(|(k, v)| (k.clone(), v.clone()))
            .collect(),
        todo: n.todo.clone(),
        priority: n.priority,
    }
}

/// An edge's payload: everything but its source.
#[derive(Debug, Clone, PartialEq)]
struct Payload {
    target: String,
    fragment: Option<String>,
    rel: String,
    weight: String,
    confidence: String,
    attrs: Vec<(String, String)>,
}

#[derive(Debug, Clone, PartialEq)]
struct Edge {
    from: String,
    p: Payload,
}

fn kb_edge(from: &str, l: &ParsedLink) -> Edge {
    Edge {
        from: from.to_string(),
        p: Payload {
            target: l.target.clone(),
            fragment: l.fragment.clone(),
            rel: l.rel_type.clone(),
            weight: format!("{}", l.weight),
            confidence: format!("{}", l.confidence),
            attrs: l.attrs.clone(),
        },
    }
}

fn sem_edges(s: &Semantics) -> Vec<Edge> {
    s.links
        .iter()
        .filter(|l| l.kind == LinkKind::Kb && !(l.target.is_empty() && l.fragment.is_none()))
        .filter_map(|l| {
            Some(Edge {
                from: l.from.clone()?,
                p: Payload {
                    target: l.target.clone(),
                    fragment: l.fragment.clone(),
                    rel: l.rel.clone(),
                    weight: format!("{}", l.weight),
                    confidence: format!("{}", l.confidence),
                    attrs: l.attrs.clone(),
                },
            })
        })
        .collect()
}

/// The common part of two multisets removed: (only in a, only in b).
fn multiset_diff<T: PartialEq + Clone>(a: &[T], b: &[T]) -> (Vec<T>, Vec<T>) {
    let mut rest: Vec<Option<T>> = b.iter().cloned().map(Some).collect();
    let mut only_a = Vec::new();
    for x in a {
        match rest.iter_mut().find(|y| y.as_ref() == Some(x)) {
            Some(slot) => *slot = None,
            None => only_a.push(x.clone()),
        }
    }
    (only_a, rest.into_iter().flatten().collect())
}

/// The Emacs oracle: (file, id, line) -> (level, title).
type Oracle = HashMap<(String, String, usize), (usize, String)>;

fn oracle_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("conformance/semantics-titles.tsv")
}

fn load_oracle() -> Oracle {
    let mut out = Oracle::default();
    for (n, line) in read(&oracle_path()).lines().enumerate() {
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let f: Vec<&str> = line.splitn(5, '\t').collect();
        let [file, id, at, level, title] = f.as_slice() else {
            panic!("semantics-titles.tsv:{}: not five fields", n + 1);
        };
        let num = |s: &str| {
            s.parse::<usize>()
                .unwrap_or_else(|_| panic!("semantics-titles.tsv:{}", n + 1))
        };
        out.insert(
            (file.to_string(), id.to_string(), num(at)),
            (num(level), title.to_string()),
        );
    }
    out
}

/// Everything a classifier may consult about one file.
struct Ctx<'a> {
    file: String,
    text: &'a str,
    doc: &'a Document,
    sem: &'a Semantics,
    oracle: &'a Oracle,
    /// mae-kb's ingest nodes (`parse_org_multi`), for bodies.
    kb_bodies: Vec<Node>,
    out: Vec<Diff>,
}

impl Ctx<'_> {
    /// Emacs's (level, title) for the node `id` starting on `line`.
    fn oracle_row(&self, id: &str, line: usize) -> Option<(usize, String)> {
        self.oracle
            .get(&(self.file.clone(), id.to_string(), line))
            .cloned()
    }

    /// Emacs's title for mae-org's node `id`.
    fn oracle_title(&self, id: &str) -> Option<&str> {
        let n = self.node(id)?;
        let line = line_of(self.text, n.span.start as usize);
        self.oracle
            .get(&(self.file.clone(), id.to_string(), line))
            .map(|r| r.1.as_str())
    }

    fn push(&mut self, what: &'static str, class: &'static str, text: String) {
        self.out.push(Diff {
            what,
            class,
            file: self.file.clone(),
            text,
        });
    }

    fn node(&self, id: &str) -> Option<&SemanticNode> {
        self.sem.nodes.iter().find(|n| n.id == id)
    }

    fn file_id(&self) -> Option<&str> {
        self.sem
            .nodes
            .iter()
            .find(|n| n.origin == NodeOrigin::File)
            .map(|n| n.id.as_str())
    }

    fn duplicated(&self, id: &str) -> bool {
        self.sem
            .diagnostics
            .iter()
            .any(|d| matches!(d, SemanticDiagnostic::DuplicateId { id: i, .. } if i == id))
    }

    fn unrendered_id(&self, id: &str) -> bool {
        self.sem
            .diagnostics
            .iter()
            .any(|d| matches!(d, SemanticDiagnostic::IdInUnrenderedRegion { id: i, .. } if i == id))
    }

    /// Whether `offset` lies in a region the semantics reported unrendered.
    fn in_unrendered(&self, offset: usize) -> bool {
        self.sem.diagnostics.iter().any(|d| match d {
            SemanticDiagnostic::IdInUnrenderedRegion { .. }
            | SemanticDiagnostic::LinkInUnrenderedRegion { .. }
            | SemanticDiagnostic::TransclusionInUnrenderedRegion { .. } => {
                d.span().range().contains(&offset)
            }
            _ => false,
        })
    }

    /// Where the text at `offset` sits, as a class: what kind of element
    /// keeps it from being what mae-kb read it as.
    fn place(&self, offset: usize) -> &'static str {
        if self.in_unrendered(offset) {
            return "unrendered_region";
        }
        let root = self.doc.syntax();
        let Some(tok) = root.token_at_offset((offset as u32).into()).right_biased() else {
            return "unclassified";
        };
        for a in tok.parent_ancestors() {
            let class = match a.kind() {
                LINK => "is_link",
                TABLE => "pending_table_cell",
                SRC_BLOCK | EXAMPLE_BLOCK => "verbatim_block",
                VERBATIM | CODE => "verbatim_object",
                FIXED_WIDTH => "verbatim_block",
                KEYWORD => "keyword_value",
                NODE_PROPERTY => "property_value",
                _ => continue,
            };
            return class;
        }
        "not_a_link_in_org"
    }
}

/// Offsets of `[[` links whose path (after blanks and `id:`) starts with
/// `target` followed by the end of the target.
fn link_occurrences(text: &str, target: &str) -> Vec<usize> {
    let mut out = Vec::new();
    let mut from = 0;
    while let Some(i) = text[from..].find("[[") {
        let at = from + i;
        from = at + 1;
        // Blanks around the path, as mae-kb trimmed them.
        let inner = text[at + 2..].trim_start_matches([' ', '\t']);
        let inner = inner.strip_prefix("id:").unwrap_or(inner);
        let after = inner
            .strip_prefix(target)
            .map(|r| r.trim_start_matches([' ', '\t']))
            .and_then(|r| r.chars().next());
        if matches!(after, Some(']' | '|' | '#' | '?')) {
            out.push(at + 2);
        }
    }
    out
}

/// The single class of the places, ignoring real links; `None` if mixed or
/// every place is a real link.
fn single_class(places: impl Iterator<Item = &'static str>) -> Option<&'static str> {
    let mut classes: Vec<&'static str> = places.filter(|c| *c != "is_link").collect();
    classes.dedup();
    match classes.as_slice() {
        [one] => Some(*one),
        _ => None,
    }
}

fn compare(file: &str, text: &str, oracle: &Oracle) -> Vec<Diff> {
    let kb = parse_org_multi_result(text);
    let doc = parse(text, &options());
    let sem = semantics(&doc);
    let mut cx = Ctx {
        file: file.to_string(),
        text,
        doc: &doc,
        sem: &sem,
        oracle,
        kb_bodies: mae_kb::org::parse_org_multi(text),
        out: Vec::new(),
    };
    compare_nodes(&mut cx, &kb.nodes);
    compare_links(&mut cx, &kb.typed_links);
    compare_transclusions(&mut cx, &kb.transclusions);
    cx.out
}

fn compare_nodes(cx: &mut Ctx, kb: &[Node]) {
    let mut first: Vec<&Node> = Vec::new();
    for n in kb {
        if !first.iter().any(|f| f.id == n.id) {
            first.push(n);
        }
    }
    for n in &first {
        match cx.node(&n.id).cloned() {
            Some(s) => {
                compare_row(cx, &n.id, &kb_row(n), &sem_row(cx.sem, &s));
                compare_oracle(cx, &s);
                compare_body(cx, &n.id, &s);
            }
            None => {
                let class = classify_kb_only_node(cx, &n.id);
                cx.push("node", class, format!("only mae-kb: {}", n.id));
            }
        }
    }
    for s in cx.sem.nodes.clone() {
        if !first.iter().any(|f| f.id == s.id) {
            cx.push("node", "unclassified", format!("only mae-org: {}", s.id));
        }
    }
}

fn classify_kb_only_node(cx: &Ctx, id: &str) -> &'static str {
    if cx.unrendered_id(id) {
        return "unrendered_region";
    }
    let line = format!(":ID: {id}");
    let places = cx.text.match_indices(&line).map(|(i, _)| cx.place(i));
    single_class(places).unwrap_or("unclassified")
}

fn compare_row(cx: &mut Ctx, id: &str, k: &Row, s: &Row) {
    let in_file_todo = cx.doc.todo_sequences() != options().todo_sequences.as_slice();
    let todo_class = if in_file_todo {
        "in_file_todo"
    } else {
        "unclassified"
    };
    if k.title != s.title {
        // Intended only where Emacs's reading agrees with mae-org's own
        // title (not the adapter's stand-in for a missing one).
        let mine = cx
            .node(id)
            .and_then(|n| n.title.clone())
            .unwrap_or_default();
        let class = if in_file_todo {
            "in_file_todo"
        } else if cx.oracle_title(id) == Some(mine.as_str()) {
            "title_matches_emacs"
        } else {
            "unclassified"
        };
        cx.push(
            "title",
            class,
            format!("{id}: {:?} vs {:?}", k.title, s.title),
        );
    }
    if k.tags != s.tags {
        let mut dedup: Vec<String> = Vec::new();
        for t in &k.tags {
            if !dedup.contains(t) {
                dedup.push(t.clone());
            }
        }
        let class = if dedup == s.tags {
            "tags_once"
        } else {
            "unclassified"
        };
        cx.push("tags", class, format!("{id}: {:?} vs {:?}", k.tags, s.tags));
    }
    if k.kind != s.kind {
        cx.push(
            "kind",
            "unclassified",
            format!("{id}: {:?} vs {:?}", k.kind, s.kind),
        );
    }
    if k.aliases != s.aliases {
        let text = format!("{id}: {:?} vs {:?}", k.aliases, s.aliases);
        cx.push("aliases", "unclassified", text);
    }
    compare_properties(cx, id, &k.properties, &s.properties);
    if k.todo != s.todo {
        cx.push(
            "todo",
            todo_class,
            format!("{id}: {:?} vs {:?}", k.todo, s.todo),
        );
    }
    if k.priority != s.priority {
        let text = format!("{id}: {:?} vs {:?}", k.priority, s.priority);
        cx.push("priority", todo_class, text);
    }
}

/// Key by key. mae-kb lower-cased keys; mae-org's must be the canonical
/// form, which for an ASCII key is its upper case, exactly: a key left as
/// written (`Last-Accessed`) is a difference, not a case variant.
fn compare_properties(
    cx: &mut Ctx,
    id: &str,
    k: &BTreeMap<String, String>,
    s: &BTreeMap<String, String>,
) {
    let mut seen: Vec<&str> = Vec::new();
    for (key, value) in s {
        let lower = key.to_ascii_lowercase();
        match k.get_key_value(&lower) {
            Some((kk, kv)) => {
                seen.push(kk);
                if kv != value {
                    let text = format!("{id}: {key}: {kv:?} vs {value:?}");
                    cx.push("properties", "unclassified", text);
                } else if *key == kk.to_ascii_uppercase() {
                    if key != kk {
                        cx.push(
                            "properties",
                            "property_key_case",
                            format!("{id}: {kk} -> {key}"),
                        );
                    }
                } else {
                    cx.push(
                        "properties",
                        "unclassified",
                        format!("{id}: key {kk} vs {key}"),
                    );
                }
            }
            None => {
                let text = format!("{id}: {key}: only mae-org {value:?}");
                cx.push("properties", "unclassified", text);
            }
        }
    }
    for (key, value) in k {
        if !seen.contains(&key.as_str()) {
            let text = format!("{id}: {key}: only mae-kb {value:?}");
            cx.push("properties", "unclassified", text);
        }
    }
}

/// The line (1-based) `offset` is on, counting line endings as Emacs does.
fn line_of(text: &str, offset: usize) -> usize {
    let before = &text[..offset];
    let lf = before.matches('\n').count();
    if lf == 0 && !text.contains('\n') {
        before.matches('\r').count() + 1
    } else {
        lf + 1
    }
}

/// mae-org's title and level against Emacs's (`semantics-titles.tsv`).
fn compare_oracle(cx: &mut Ctx, n: &SemanticNode) {
    let line = line_of(cx.text, n.span.start as usize);
    let Some((level, title)) = cx.oracle_row(&n.id, line) else {
        cx.push(
            "oracle",
            "missing_row",
            format!(
                "{}:{line}: no Emacs row for {}; run conformance/gen-semantics-titles.sh",
                cx.file, n.id
            ),
        );
        return;
    };
    let mine = n.title.clone().unwrap_or_default();
    if mine != title {
        let text = format!("{}: mae-org {mine:?} vs Emacs {title:?}", n.id);
        cx.push("title", "oracle_title", text);
    }
    if n.level != level {
        let text = format!("{}: mae-org {} vs Emacs {level}", n.id, n.level);
        cx.push("level", "unclassified", text);
    }
}

/// A body is compared as an extent: which text of the document is the
/// node's. The reference is mae-kb's INGEST parser, `parse_org_multi`, whose
/// file body skips the header (#655); `parse_org_multi_result`, which
/// `kb_build` uses and the other fields are compared with, still keeps the
/// whole file as the file node's body, a drift inside mae-kb. mae-kb stored
/// `rewrite_links` of a range of lines, so mae-org's
/// body goes through the same function, and both lose trailing line endings
/// (mae-kb joined lines). Where they differ, the class names how mae-kb's
/// range relates to mae-org's, checked by rebuilding it from mae-org's spans:
/// - `body_front_matter`: mae-kb's body also holds the element's front
///   matter (the headline or item line, planning, property drawer), from the
///   element's start;
/// - `body_past_nested_node`: mae-kb's body runs past the first node nested
///   in the element, to the element's end (or, for the file, the end of the
///   text), so it holds that node, its drawer and its id;
/// - both, joined by `+`.
fn compare_body(cx: &mut Ctx, id: &str, n: &SemanticNode) {
    let norm = |t: &str| rewrite_links(t).trim_end_matches(['\n', '\r']).to_string();
    let body = n.body_span.range();
    let Some(k) = cx.kb_bodies.iter().find(|k| k.id == id) else {
        return;
    };
    let want = k.body.trim_end_matches(['\n', '\r']).to_string();
    if norm(&cx.text[body.clone()]) == want {
        return;
    }
    let starts = [
        (body.start, ""),
        (n.span.start as usize, "body_front_matter"),
    ];
    // Clipped only where a node nested in this one starts at the body's end.
    let clipped = body.end < n.span.end as usize
        && cx
            .sem
            .nodes
            .iter()
            .any(|m| m.span.start as usize == body.end && n.span.start < m.span.start);
    let mut ends = vec![(body.end, "")];
    if clipped {
        ends.push((n.span.end as usize, "body_past_nested_node"));
    }
    let mut class = "unclassified";
    'found: for (a, ca) in starts {
        for &(b, cb) in &ends {
            if a <= b && norm(&cx.text[a..b]) == want {
                class = match (ca, cb) {
                    ("", "") => "unclassified",
                    (x, "") | ("", x) => x,
                    _ => "body_front_matter+body_past_nested_node",
                };
                break 'found;
            }
        }
    }
    let text = format!("{}: {} bytes vs {} bytes", n.id, want.len(), body.len());
    cx.push("body", class, text);
}

fn compare_links(cx: &mut Ctx, kb: &[(String, ParsedLink)]) {
    let kb_edges: Vec<Edge> = kb.iter().map(|(f, l)| kb_edge(f, l)).collect();
    let sem_edges = sem_edges(cx.sem);
    let (mut only_kb, mut only_sem) = multiset_diff(&kb_edges, &sem_edges);
    pair_moved_edges(cx, &mut only_kb, &mut only_sem);
    pair_search_options(cx, &mut only_kb, &mut only_sem);
    classify_kb_only_edges(cx, only_kb);
    let mut plain_spent: Vec<(Edge, usize)> = Vec::new();
    for e in only_sem {
        let used = match plain_spent.iter_mut().find(|u| u.0 == e) {
            Some(u) => {
                u.1 += 1;
                u.1
            }
            None => {
                plain_spent.push((e.clone(), 1));
                1
            }
        };
        let class = classify_sem_only_edge(cx, &e, &kb_edges, used);
        cx.push("link", class, format!("only mae-org: {e:?}"));
    }
}

/// mae-org's links that make the edge `e`.
fn links_of<'a>(cx: &'a Ctx, e: &Edge) -> Vec<&'a mae_org::SemanticLink> {
    cx.sem
        .links
        .iter()
        .filter(|l| {
            l.kind == LinkKind::Kb
                && l.from.as_deref() == Some(e.from.as_str())
                && l.target == e.p.target
                && l.fragment == e.p.fragment
                && l.rel == e.p.rel
                && format!("{}", l.weight) == e.p.weight
                && format!("{}", l.confidence) == e.p.confidence
                && l.attrs == e.p.attrs
        })
        .collect()
}

/// The tree's LINK at a semantic link's span, if the link is in the tree
/// (a link in a keyword or property value is not).
fn tree_link(cx: &Ctx, l: &mae_org::SemanticLink) -> Option<mae_org::Link> {
    let tok = cx
        .doc
        .syntax()
        .token_at_offset(l.span.start.into())
        .right_biased()?;
    tok.parent_ancestors()
        .find(|a| a.kind() == LINK && u32::from(a.text_range().start()) == l.span.start)
        .and_then(mae_org::Link::cast)
}

/// An `[[id:X::SEARCH]]` edge: mae-kb's target kept `::SEARCH` (an id that
/// never exists); mae-org's is `X`, from the same source, the rest equal.
fn pair_search_options(cx: &mut Ctx, only_kb: &mut Vec<Edge>, only_sem: &mut Vec<Edge>) {
    let mut i = 0;
    while i < only_kb.len() {
        let e = &only_kb[i];
        let Some(id) = e.p.target.split_once("::").map(|p| p.0.to_string()) else {
            i += 1;
            continue;
        };
        let mut want = e.clone();
        want.p.target = id.clone();
        let searched = links_of(cx, &want).iter().any(|l| l.search.is_some());
        match only_sem.iter().position(|f| *f == want) {
            Some(j) if searched => {
                only_sem.remove(j);
                let e = only_kb.remove(i);
                cx.push("link", "id_search_option", format!("{e:?} -> {id}"));
            }
            _ => i += 1,
        }
    }
}

/// An edge both sides have, from different sources, where mae-kb's source
/// is not a node in mae-org: the content belongs to the node around it.
fn pair_moved_edges(cx: &mut Ctx, only_kb: &mut Vec<Edge>, only_sem: &mut Vec<Edge>) {
    let mut i = 0;
    while i < only_kb.len() {
        let e = &only_kb[i];
        let gone = cx.node(&e.from).is_none() || cx.duplicated(&e.from);
        let partner = only_sem.iter().position(|f| f.p == e.p);
        match partner {
            Some(j) if gone => {
                let f = only_sem.remove(j);
                let e = only_kb.remove(i);
                let class = if cx.duplicated(&e.from) {
                    "duplicate_id"
                } else {
                    "source_not_a_node"
                };
                cx.push("link", class, format!("moved: {e:?} -> {}", f.from));
            }
            _ => i += 1,
        }
    }
}

/// How many of mae-org's edges with `e`'s payload come from nodes strictly
/// inside `e`'s source: mae-kb's headline body runs to the next headline of
/// the same level, so it also counts each of these for every ancestor.
fn descendant_count(cx: &Ctx, e: &Edge) -> usize {
    let Some(parent) = cx.node(&e.from).map(|n| n.span) else {
        return 0;
    };
    sem_edges(cx.sem)
        .iter()
        .filter(|f| f.p == e.p && f.from != e.from)
        .filter_map(|f| cx.node(&f.from).map(|n| n.span))
        .filter(|c| parent.start <= c.start && c.end <= parent.end)
        .count()
}

/// mae-kb-only edges: an edge counted again for an ancestor is explained
/// only up to the number of descendant edges that account for it.
fn classify_kb_only_edges(cx: &mut Ctx, only_kb: Vec<Edge>) {
    let mut spent: Vec<(Edge, usize)> = Vec::new();
    for e in only_kb {
        let n = match spent.iter_mut().find(|u| u.0 == e) {
            Some(u) => {
                u.1 += 1;
                u.1
            }
            None => {
                spent.push((e.clone(), 1));
                1
            }
        };
        let class = if n <= descendant_count(cx, &e) {
            "ancestor_double_count"
        } else {
            classify_kb_only_edge(cx, &e)
        };
        cx.push("link", class, format!("only mae-kb: {e:?}"));
    }
}

fn classify_kb_only_edge(cx: &Ctx, e: &Edge) -> &'static str {
    // `[[#c]]`, `[[*h]]`, `[[(r)]]`: mae-kb made an edge (`#c` a fragment of
    // an empty target); mae-org has the same link, from the same source, as
    // a local target.
    let local = cx.sem.links.iter().any(|l| {
        l.from.as_deref() == Some(e.from.as_str())
            && match l.kind {
                LinkKind::CustomId => {
                    e.p.target.is_empty() && e.p.fragment.as_ref() == Some(&l.target)
                }
                LinkKind::Heading => e.p.target == format!("*{}", l.target),
                LinkKind::Coderef => e.p.target == format!("({})", l.target),
                _ => false,
            }
    });
    if local {
        return "local_target";
    }
    if classify_link(&e.p.target).kind != LinkKind::Kb {
        return "external_classifier";
    }

    let places = link_occurrences(cx.text, &e.p.target)
        .into_iter()
        .map(|i| cx.place(i));
    single_class(places).unwrap_or("unclassified")
}

/// mae-kb drops a file-level edge when any headline has the same target and
/// relation, even where the file's own text links it too. Only an edge whose
/// link lies in the zeroth section can be such a drop.
/// `used`: how many edges equal to `e` were classified before this one,
/// itself included; a plain link explains only as many as there are plain
/// links making exactly this edge.
fn classify_sem_only_edge(cx: &Ctx, e: &Edge, kb: &[Edge], used: usize) -> &'static str {
    let first_headline = cx
        .doc
        .headlines()
        .next()
        .map_or(usize::MAX, |h| usize::from(h.syntax().text_range().start()));
    let in_zeroth = cx.sem.links.iter().any(|l| {
        l.from.as_deref() == Some(e.from.as_str())
            && l.target == e.p.target
            && (l.span.start as usize) < first_headline
    });
    let on_a_headline = kb
        .iter()
        .any(|k| k.from != e.from && k.p.target == e.p.target && k.p.rel == e.p.rel);
    let plain = links_of(cx, e)
        .into_iter()
        .filter(|l| tree_link(cx, l).is_some_and(|t| t.format() == mae_org::LinkFormat::Plain))
        .count()
        >= used;
    if Some(e.from.as_str()) == cx.file_id() && in_zeroth && on_a_headline {
        "file_link_dedup"
    } else if plain {
        "plain_link"
    } else {
        "unclassified"
    }
}

fn compare_transclusions(cx: &mut Ctx, kb: &[(String, String, String)]) {
    let sem: Vec<(String, String, String)> = cx
        .sem
        .transclusions
        .iter()
        .filter_map(|t| Some((t.from.clone()?, t.member.clone(), t.role.clone())))
        .collect();
    let (mut only_kb, mut only_sem) = multiset_diff(kb, &sem);
    // Same directive, attributed to the node around it rather than the file.
    only_kb.retain(|k| {
        let Some(j) = only_sem.iter().position(|s| s.1 == k.1 && s.2 == k.2) else {
            return true;
        };
        let s = only_sem.remove(j);
        cx.push(
            "transclusion",
            "innermost_node",
            format!("{k:?} -> {}", s.0),
        );
        false
    });
    for t in only_kb {
        let places = transclusion_lines(cx.text, &t.1).map(|i| cx.place(i));
        let class = single_class(places).unwrap_or("unclassified");
        cx.push("transclusion", class, format!("only mae-kb: {t:?}"));
    }
    for t in only_sem {
        let exact = ["#+TRANSCLUDE:", "#+transclude:"];
        let class = if exact
            .iter()
            .any(|p| cx.text.contains(&format!("{p} {}", t.1)))
        {
            "unclassified"
        } else {
            "keyword_case"
        };
        cx.push("transclusion", class, format!("only mae-org: {t:?}"));
    }
}

fn transclusion_lines<'a>(text: &'a str, member: &'a str) -> impl Iterator<Item = usize> + 'a {
    text.match_indices(member)
        .map(|(i, _)| i)
        .filter(move |&i| {
            let line_start = text[..i].rfind('\n').map_or(0, |n| n + 1);
            text[line_start..i]
                .trim_start()
                .to_ascii_lowercase()
                .starts_with("#+transclude:")
        })
}

// ---------------------------------------------------------------- register

#[derive(Debug)]
struct Entry {
    what: String,
    class: String,
    file: String,
    detail: String,
    /// For a wildcard entry: exactly how many differences it covers.
    count: Option<usize>,
    test: String,
    line: usize,
}

impl Entry {
    fn matches(&self, d: &Diff) -> bool {
        let file_ok = match self.file.strip_suffix('*') {
            Some(prefix) => d.file.starts_with(prefix),
            None => d.file == self.file,
        };
        self.what == d.what && self.class == d.class && file_ok && d.text.contains(&self.detail)
    }
}

fn register_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("conformance/semantics-divergences.toml")
}

/// The register: `[[divergence]]` tables of `key = "string"` lines.
fn load_register() -> Vec<Entry> {
    let text = read(&register_path());
    let mut rows: Vec<(usize, HashMap<String, String>)> = Vec::new();
    for (n, line) in text.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if line == "[[divergence]]" {
            rows.push((n + 1, HashMap::default()));
            continue;
        }
        let (k, v) = line
            .split_once('=')
            .unwrap_or_else(|| panic!("register:{}: not `key = value`", n + 1));
        let v = v.trim();
        let v = v.strip_prefix('"').and_then(|v| v.strip_suffix('"'));
        let v = v.unwrap_or_else(|| panic!("register:{}: value must be a string", n + 1));
        let row = rows
            .last_mut()
            .unwrap_or_else(|| panic!("register:{}: outside a table", n + 1));
        row.1.insert(k.trim().to_string(), v.replace("\\\"", "\""));
    }
    rows.into_iter().map(entry).collect()
}

/// One entry, checked for selectivity: an entry for one file names the
/// difference (`detail`); a wildcard entry pins how many it covers.
fn entry((line, mut m): (usize, HashMap<String, String>)) -> Entry {
    let mut take = |k: &str| m.remove(k).unwrap_or_default();
    let count = take("count");
    let e = Entry {
        what: take("what"),
        class: take("class"),
        file: take("file"),
        detail: take("detail"),
        count: (!count.is_empty()).then(|| {
            count
                .parse()
                .unwrap_or_else(|_| panic!("register:{line}: count must be a number"))
        }),
        test: take("test"),
        line,
    };
    let reason = take("reason");
    assert!(
        !e.what.is_empty() && !e.class.is_empty() && !e.file.is_empty(),
        "register:{line}: what, class and file are required"
    );
    assert!(
        !reason.is_empty() && !e.test.is_empty(),
        "register:{line}: reason and test are required"
    );
    assert!(m.is_empty(), "register:{line}: unknown keys {:?}", m.keys());
    assert!(
        e.file == "*" || !e.detail.is_empty(),
        "register:{line}: an entry that is not for every file needs a detail"
    );
    assert!(
        !e.file.ends_with('*') || e.count.is_some(),
        "register:{line}: a wildcard entry needs a count"
    );
    e
}

/// Every name of a `#[test]` function in this crate's sources: a `fn NAME(`
/// whose attributes (above it, past doc comments) include `#[test]`.
fn test_functions() -> Vec<String> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let mut names = Vec::new();
    for dir in ["src", "tests"] {
        let mut stack = vec![root.join(dir)];
        while let Some(d) = stack.pop() {
            for e in std::fs::read_dir(&d).into_iter().flatten().flatten() {
                let p = e.path();
                if p.is_dir() {
                    stack.push(p);
                } else if p.extension().is_some_and(|x| x == "rs") {
                    names.extend(tests_in(&read(&p)));
                }
            }
        }
    }
    names
}

fn tests_in(source: &str) -> Vec<String> {
    let lines: Vec<&str> = source.lines().map(str::trim).collect();
    let mut out = Vec::new();
    for (i, l) in lines.iter().enumerate() {
        let Some(rest) = l.strip_prefix("fn ") else {
            continue;
        };
        let Some(name) = rest.split('(').next().filter(|n| !n.contains(' ')) else {
            continue;
        };
        let attrs = lines[..i]
            .iter()
            .rev()
            .take_while(|p| p.starts_with("#[") || p.starts_with("///") || p.starts_with("//"));
        if attrs.into_iter().any(|p| *p == "#[test]") {
            out.push(name.to_string());
        }
    }
    out
}

/// Every pinning test named by the register is a `#[test]` function.
fn assert_tests_exist(register: &[Entry]) {
    let tests = test_functions();
    for e in register {
        assert!(
            tests.contains(&e.test),
            "register:{}: pinning test `{}` is not a #[test] function",
            e.line,
            e.test
        );
    }
}

/// Sizes of both projections over `files`, for the report.
fn print_totals(label: &str, files: &[PathBuf]) {
    let mut t = [0usize; 6];
    for path in files {
        let text = read(path);
        let kb = parse_org_multi_result(&text);
        let sem = semantics(&parse(&text, &options()));
        let tr = sem
            .transclusions
            .iter()
            .filter(|x| x.from.is_some())
            .count();
        let c = [
            kb.nodes.len(),
            sem.nodes.len(),
            kb.typed_links.len(),
            sem_edges(&sem).len(),
            kb.transclusions.len(),
            tr,
        ];
        t.iter_mut().zip(c).for_each(|(a, b)| *a += b);
    }
    println!(
        "{label}: {} files; nodes mae-kb {} / mae-org {}; edges {} / {}; transclusions {} / {}",
        files.len(),
        t[0],
        t[1],
        t[2],
        t[3],
        t[4],
        t[5]
    );
}

fn synthetic() -> Vec<PathBuf> {
    support::org_files(&Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/semantics"))
}

#[test]
fn semantics_agree_with_mae_kb_except_registered_divergences() {
    let register = load_register();
    assert_tests_exist(&register);
    let oracle = load_oracle();
    let files: Vec<PathBuf> = bundled_corpus().into_iter().chain(synthetic()).collect();
    let mut diffs = Vec::new();
    for path in &files {
        diffs.extend(compare(&rel(path), &read(path), &oracle));
    }
    print_totals("bundled corpus", &bundled_corpus());
    print_totals("synthetic", &synthetic());
    // The oracle covers every node and only files of the corpus: anything
    // else means it is stale.
    let missing: Vec<&str> = diffs
        .iter()
        .filter(|d| d.class == "missing_row")
        .map(|d| d.text.as_str())
        .collect();
    assert!(missing.is_empty(), "{}", missing.join("\n"));
    let names: Vec<String> = files.iter().map(|p| rel(p)).collect();
    let foreign: Vec<&String> = oracle
        .keys()
        .map(|k| &k.0)
        .filter(|f| !names.contains(f))
        .collect();
    assert!(
        foreign.is_empty(),
        "semantics-titles.tsv names files not in the corpus (regenerate it): {foreign:?}"
    );
    let unlisted: Vec<String> = diffs
        .iter()
        .filter(|d| !register.iter().any(|e| e.matches(d)))
        .map(|d| format!("{} [{} / {}] {}", d.file, d.what, d.class, d.text))
        .collect();
    let mut stale = Vec::new();
    for e in &register {
        let hits = diffs.iter().filter(|d| e.matches(d)).count();
        let line = format!(
            "line {}: {} / {} / {} {:?}",
            e.line, e.what, e.class, e.file, e.detail
        );
        if hits == 0 {
            stale.push(format!("{line}: no longer occurs"));
        } else if e.count.is_some_and(|c| c != hits) {
            stale.push(format!(
                "{line}: count {} but {hits} differences",
                e.count.unwrap_or(0)
            ));
        }
    }
    let mut counts: BTreeMap<(&str, &str), usize> = BTreeMap::new();
    for d in &diffs {
        *counts.entry((d.what, d.class)).or_default() += 1;
    }
    println!(
        "{} files, {} differences: {counts:#?}",
        files.len(),
        diffs.len()
    );
    assert!(
        unlisted.is_empty(),
        "differences not in the register:\n{}",
        unlisted.join("\n")
    );
    assert!(
        stale.is_empty(),
        "register entries that no longer match as registered:\n{}",
        stale.join("\n")
    );
}

/// The adapter and classifiers cannot hide a real disagreement: a node
/// title, a link source, a property value, a property key left as written,
/// a level, a tag and a body changed in mae-org's output each surface as a
/// difference no intended class explains.
#[test]
fn the_differential_reports_an_injected_disagreement() {
    let text = ":PROPERTIES:\n:ID: f\n:END:\n#+title: T\n\n* H\n:PROPERTIES:\n:ID: h\n:X: 1\n:Y: 2\n:END:\nsee [[id:t]]\n";
    let oracle: Oracle = [
        (
            ("x.org".to_string(), "f".to_string(), 1),
            (0, "T".to_string()),
        ),
        (
            ("x.org".to_string(), "h".to_string(), 6),
            (1, "H".to_string()),
        ),
    ]
    .into_iter()
    .collect();
    let base = compare("x.org", text, &oracle);
    let classes: Vec<(&str, &str)> = base.iter().map(|d| (d.what, d.class)).collect();
    assert_eq!(
        classes,
        vec![
            ("body", "body_past_nested_node"),
            ("properties", "property_key_case"),
            ("properties", "property_key_case"),
            ("body", "body_front_matter"),
        ]
    );
    let kb = parse_org_multi_result(text);
    let doc = parse(text, &options());
    let mut sem = semantics(&doc);
    sem.nodes[1].title = Some("changed".into());
    sem.nodes[1].properties[1].1 = "2".into();
    sem.nodes[1].properties[2].0 = "y".into();
    sem.nodes[1].level = 2;
    sem.nodes[1].own_tags.push("extra".into());
    sem.nodes[1].body_span.end -= 2;
    sem.links[0].from = Some("f".into());
    let mut cx = Ctx {
        file: "x.org".into(),
        text,
        doc: &doc,
        sem: &sem,
        oracle: &oracle,
        kb_bodies: mae_kb::org::parse_org_multi(text),
        out: Vec::new(),
    };
    compare_nodes(&mut cx, &kb.nodes);
    compare_links(&mut cx, &kb.typed_links);
    let got: Vec<(&str, &str)> = cx.out.iter().map(|d| (d.what, d.class)).collect();
    for want in [
        ("title", "unclassified"),
        ("title", "oracle_title"),
        ("level", "unclassified"),
        ("tags", "unclassified"),
        ("body", "unclassified"),
    ] {
        assert!(got.contains(&want), "{want:?} not in {got:?}");
    }
    let props: Vec<&str> = cx
        .out
        .iter()
        .filter(|d| d.what == "properties" && d.class == "unclassified")
        .map(|d| d.text.as_str())
        .collect();
    assert_eq!(props, vec!["h: X: \"1\" vs \"2\"", "h: key y vs y"]);
    assert!(
        got.iter()
            .filter(|g| g.0 == "link")
            .all(|g| g.1 == "unclassified"),
        "{got:?}"
    );
    assert!(got.iter().any(|g| g.0 == "link"), "{got:?}");
}

/// `plain_link` excuses an edge only when a plain link makes exactly that
/// edge (same source, same payload): moving a bracket link's source onto a
/// node that only has a plain link to the same target is not excused.
#[test]
fn a_plain_link_excuses_only_its_own_edge() {
    let text = ":PROPERTIES:\n:ID: f\n:END:\n* A\n:PROPERTIES:\n:ID: a\n:END:\n[[id:tx]]\n* B\n:PROPERTIES:\n:ID: b\n:END:\nid:tx\n* C\n:PROPERTIES:\n:ID: c\n:END:\n";
    let oracle = Oracle::default();
    let kb = parse_org_multi_result(text);
    let doc = parse(text, &options());
    let run = |sem: &Semantics| {
        let mut cx = Ctx {
            file: "x.org".into(),
            text,
            doc: &doc,
            sem,
            oracle: &oracle,
            kb_bodies: Vec::new(),
            out: Vec::new(),
        };
        compare_links(&mut cx, &kb.typed_links);
        cx.out
            .into_iter()
            .map(|d| {
                (
                    d.class,
                    d.text.contains("from: \"b\"") || d.text.contains("from: \"c\""),
                )
            })
            .collect::<Vec<_>>()
    };
    let sem = semantics(&doc);
    assert_eq!(run(&sem), vec![("plain_link", true)]);
    let mut moved = sem.clone();
    let i = moved
        .links
        .iter()
        .position(|l| l.from.as_deref() == Some("a"))
        .unwrap();
    moved.links[i].from = Some("c".into());
    let got = run(&moved);
    assert!(got.contains(&("plain_link", true)), "{got:?}");
    assert_eq!(
        got.iter().filter(|g| g.0 == "plain_link").count(),
        1,
        "{got:?}"
    );
    assert!(got.iter().any(|g| g.0 == "unclassified" && g.1), "{got:?}");
}

/// The register's pinning-test check sees `#[test]` functions only, not a
/// helper or a mention of the name.
#[test]
fn only_real_test_functions_pin_entries() {
    let src = "/// doc\n#[test]\nfn real() {}\n\nfn helper() {}\n// fn mention() {}\n#[test]\n#[ignore]\nfn ignored_too() {}\nproptest! {\n    #[test]\n    fn prop(x in 0..1) {}\n}\n";
    assert_eq!(tests_in(src), vec!["real", "ignored_too", "prop"]);
}
